package com.library.dao; import com.library.model.Category; import com.library.util.DBConnection; import java.sql.*; import java.util.*;
public class CategoryDAO { public List<Category> findAll(){List<Category> list=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT category_id,category_name FROM categories ORDER BY category_name");ResultSet r=p.executeQuery()){while(r.next())list.add(new Category(r.getLong(1),r.getString(2)));}catch(SQLException e){throw new RuntimeException("Unable to load categories.",e);}return list;} }
